<?php
declare(strict_types=1);
require_once __DIR__.'/ResearchExecutionTest.php';
use DigiForge\Research\{ResearchExecution,ResearchExecutionJournal};
use DigiForge\AI\{MonetaryReservationRepository,ProviderEvidenceRepository,ShopAiGovernanceRepository};
final class ResearchReconciliationTest extends WP_UnitTestCase {
 use PhotoWorkflowFixtureIsolation {tearDown as private restoreFixture;}
 private array $floors=[];
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();ShopAccessFixture::reset();$this->capturePhotoFixtureState();global $wpdb;foreach(['jobs','ai_models','ai_tasks']as $m){$t=DigiForge\Database\Tables::{$m}();$this->floors[$t]=(int)$wpdb->get_var('SELECT COALESCE(MAX(id),0) FROM '.$t);}wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));ShopAccessFixture::authorizeActor(get_current_user_id(),['personalized_pod'],['manage_digiforge_pod','manage_digiforge_research','manage_digiforge_ai']);DigiForge\Core\Settings::protectProduction();$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');}
 protected function tearDown():void {global $wpdb;foreach(array_reverse($this->floors,true)as $t=>$id)$wpdb->query('DELETE FROM '.$t.' WHERE id>'.(int)$id);$this->restoreFixture();}
 private function checked($v):array {self::assertNotWPError($v,is_wp_error($v)?$v->get_error_code():'');return $v;}
 private function bound(bool $meter=true):array {
  $helper=new ResearchExecutionTest();[, $source,,$run]=(new ReflectionMethod($helper,'boot'))->invoke($helper);$s=new ResearchExecution();(new ReflectionMethod($helper,'quote'))->invoke($helper,$s,$source,$run);$j=$this->checked((new ReflectionMethod($helper,'enqueue'))->invoke($helper,$s,$source,$run));$q=new DigiForge\Queue\JobRepository();self::assertTrue($q->acquireLease($j['id'],'synthetic_statement_fixture',60));self::assertTrue($q->start($j['id'],'synthetic_statement_fixture'));$jr=new ResearchExecutionJournal();$j=$this->checked($jr->append($j['id'],$j['event_sha256'],['state'=>'RESERVING']));$c=$j['identity']['contracts'][0];$quote=$this->checked((new MonetaryReservationRepository())->findQuote('personalized_pod',$c));$u=$this->checked((new ShopAiGovernanceRepository())->reserveGeneration('personalized_pod','research','research-queue-'.$j['id'].'-0',$run,$quote,$c));$j=$this->checked($jr->append($j['id'],$j['event_sha256'],['state'=>'RESERVED','usage_id'=>(int)$u['id']]));$j=$this->checked($jr->append($j['id'],$j['event_sha256'],['state'=>'DISPATCHING']));$env=['response_id'=>'resp_synthetic_statement_'.str_replace('-','',wp_generate_uuid4()),'model'=>$c['model'],'status'=>'completed','usage'=>['input_tokens'=>10,'output_tokens'=>5,'total_tokens'=>15],'provider_response_sha256'=>hash('sha256','SYNTHETIC normalized metering fixture, not a provider call')];if($meter)$this->checked((new ProviderEvidenceRepository())->recordOutcome((int)$u['id'],'personalized_pod',$env));$j=$this->checked($jr->append($j['id'],$j['event_sha256'],['state'=>'UNKNOWN','response_id'=>$env['response_id']]));$doc=['provider'=>'openai','invoice_id'=>'synthetic-'.wp_generate_uuid4(),'evidence_kind'=>'SYNTHETIC_TEST_ONLY','lines'=>[['line_id'=>'one','response_id'=>$env['response_id'],'model'=>$c['model'],'currency'=>'USD','amount'=>'0.010000']]];return [$s,$j,(int)$u['id'],$doc];
 }
 private function reconcile(array $f,array $doc):array|WP_Error {self::assertTrue(method_exists($f[0],'reconcile'),'Research needs exact-job-bound review of original statement bytes through the existing ledger.');return $f[0]->reconcile('personalized_pod',$f[1]['id'],$f[1]['event_sha256'],$f[2],json_encode($doc),true);}
 public function testStatementReviewReconcilesExactUsageAndReplaysWithoutInventingRefund():void {
  $f=$this->bound();$money=new MonetaryReservationRepository();$before=$this->checked($money->exposure('personalized_pod','USD',$f[1]['identity']['run_context']['run_id']));self::assertSame(20000,$before['run']);$cost=$this->checked($this->reconcile($f,$f[3]));self::assertSame('0.010000',$cost['items'][0]['actual_charge']);self::assertFalse($cost['refund_assumed']);self::assertSame($cost,$this->checked($this->reconcile($f,$f[3])));$after=$this->checked($money->exposure('personalized_pod','USD',$f[1]['identity']['run_context']['run_id']));self::assertSame(10000,$after['run']);self::assertSame('UNKNOWN',$this->checked($f[0]->read('personalized_pod',$f[1]['id']))['state'],'Financial evidence does not manufacture a successful research result.');
 }
 public function testMissingMeteringForeignUsageStaleEventAndUnconfirmedZeroStayHeld():void {
  $f=$this->bound(false);$doc=$f[3];$doc['lines'][0]['amount']='0.000000';self::assertWPError($this->reconcile($f,$doc));self::assertSame(20000,$this->checked((new MonetaryReservationRepository())->exposure('personalized_pod','USD',$f[1]['identity']['run_context']['run_id']))['run']);self::assertWPError($f[0]->reconcile('personalized_pod',$f[1]['id'],str_repeat('f',64),$f[2],json_encode($doc),true));self::assertWPError($f[0]->reconcile('personalized_pod',$f[1]['id'],$f[1]['event_sha256'],$f[2]+100000,json_encode($doc),true));self::assertWPError($f[0]->reconcile('personalized_pod',$f[1]['id'],$f[1]['event_sha256'],$f[2],json_encode($doc),false));self::assertWPError($f[0]->reconcile('digital',$f[1]['id'],$f[1]['event_sha256'],$f[2],json_encode($doc),true));
 }
 public function testAuthoritativeZeroLineCanClearExposureWithoutClaimingRefundOrResearchSuccess():void {
  $f=$this->bound();$doc=$f[3];$doc['lines'][0]['amount']='0.000000';$cost=$this->checked($this->reconcile($f,$doc));self::assertSame('0.000000',$cost['items'][0]['actual_charge']);self::assertFalse($cost['refund_assumed']);self::assertSame(0,$this->checked((new MonetaryReservationRepository())->exposure('personalized_pod','USD',$f[1]['identity']['run_context']['run_id']))['run']);$snap=$this->checked((new ProviderEvidenceRepository())->snapshot($f[2],'personalized_pod'));self::assertSame(hash('sha256',json_encode($doc)),$snap['settlement']['charge']['source_sha256']);
 }
 public function testOverCeilingStatementIsRetainedAndBlocksFurtherAdmission():void {
  $f=$this->bound();$doc=$f[3];$doc['lines'][0]['amount']='0.030000';self::assertWPError($this->reconcile($f,$doc));self::assertSame('RESERVATION_BOUND_EXCEEDED',$this->checked((new ProviderEvidenceRepository())->snapshot($f[2],'personalized_pod'))['cost_state']);self::assertWPError((new MonetaryReservationRepository())->exposure('personalized_pod','USD',$f[1]['identity']['run_context']['run_id']));
 }
 public function testSimulatorCannotBecomeActualChargeThroughStatementUpload():void {
  $h=new ResearchExecutionTest();[$s,$source,,$run]=(new ReflectionMethod($h,'boot'))->invoke($h);(new ReflectionMethod($h,'quote'))->invoke($h,$s,$source,$run);$j=$this->checked((new ReflectionMethod($h,'enqueue'))->invoke($h,$s,$source,$run));$j=$this->checked($s->step('personalized_pod',$j['id'],$j['event_sha256']));self::assertWPError($s->reconcile('personalized_pod',$j['id'],$j['event_sha256'],$j['usage_id'],'{"provider":"openai"}',true));self::assertNull($this->checked($s->costEvidence('personalized_pod',$j['id']))['items'][0]['actual_charge']);
 }
 public function testDuplicateOrChangedStatementCannotClearUnknownHold():void {
  $f=$this->bound();$bad=$f[3];$bad['lines'][]=$bad['lines'][0];self::assertWPError($this->reconcile($f,$bad));$bad=$f[3];$bad['lines'][0]['response_id']='resp_foreign';self::assertWPError($this->reconcile($f,$bad));$this->checked($this->reconcile($f,$f[3]));$bad=$f[3];$bad['lines'][0]['amount']='0.000000';self::assertWPError($this->reconcile($f,$bad));wp_get_current_user()->add_cap('manage_digiforge_ai',false);self::assertWPError($this->reconcile($f,$f[3]));
 }
}
